    '欢迎语与群规':['settings','运营'], '新成员验证':['security','防广告'], '入群筛查与系统提示':['security','防广告'], '定时公告':['settings','运营'], '群活跃统计':['records','数据'], '推广短链接':['global','推广'], '反入群轰炸':['security','防广告'], '夜间静默':['settings','运营'],
    '链接域名名单':['security','防广告'], '关键词命中统计':['records','数据'], '处理记录':['records','记录'], '成员举报':['records','记录'], '纠错指令':['settings','说明']
