    $('chats').replaceChildren(new Option('请选择群',''),...registeredChats.map(c=>new Option(c.title+' ('+c.id+')',c.id)));
    if(registeredChats.some(c=>c.id===selected)){$('chats').value=selected;$('chatId').value=selected;}
    $('chatListStatus').textContent=registeredChats.length?'已登记 '+registeredChats.length+' 个群':'暂无已登记群；可填写群 ID。';
    return registeredChats;
