async function loadAutomaticBackups(){
  const data=await api('backup/status');$('automaticBackupStatus').textContent=(data.enabled?data.schedule+'；保留最近 '+data.retention+' 份。':'每周自动备份已关闭。')+(data.last?'最近结果：'+(data.last.outcome==='success'?'已保存':'未完成')+' · '+new Date(data.last.at).toLocaleString()+(data.last.error?' · '+data.last.error:''):'尚未生成，首次启用后自动保存。');
  $('automaticBackups').replaceChildren(...(data.backups||[]).map(item=>{const row=document.createElement('article'),label=document.createElement('p');label.textContent=new Date(item.created).toLocaleString()+' · '+item.groups+' 个群 · '+item.samples+' 个样本';const download=document.createElement('button');download.textContent='下载这份备份';download.onclick=safe(async()=>{showBackupDownload(await api('backup/automatic?id='+encodeURIComponent(item.id)));saved(null,'备份已读取，请点击下载。');});const restore=document.createElement('button');restore.textContent='选作恢复来源';restore.onclick=safe(async()=>{$('backupText').value=JSON.stringify(await api('backup/automatic?id='+encodeURIComponent(item.id)),null,2);$('backupFile').value='';saved(null,'已填入此备份，请点击预览恢复差异，确认后才会恢复。');});row.append(label,download,restore);return row;}));
}
