async function saveWelcome(){const minutes=$('welcomeDeleteMinutes').value;if($('welcomeEnabled').checked&&!$('welcomeMessage').value.trim())$('welcomeMessage').value='👋 欢迎 {name} 加入 **{group}**！';await api('welcome-rules',{chatId:chat(),welcomeMessage:$('welcomeMessage').value,rulesMessage:$('rulesMessage').value,enabled:$('welcomeEnabled').checked,buttons:$('welcomeButtons').value,keepLatest:$('welcomeKeepLatest').checked,showCount:$('welcomeShowCount').checked,banner:$('welcomeBannerMode').value==='custom'?$('welcomeBannerUrl').value.trim():$('welcomeBannerMode').value,...(minutes===''?{}:{deleteMinutes:Number(minutes)})});legacy=false;}
