function renderLinks(data){const box=$('links');box.replaceChildren();const list=data.links||[];
  if(!list.length){const tip=document.createElement('p');tip.className='empty-tip';tip.textContent='还没有短链接。填上面的表单添加第一个。';box.append(tip);return;}
  for(const link of list){const row=document.createElement('article'),title=document.createElement('p'),stats=document.createElement('p'),target=document.createElement('p');
    const strong=document.createElement('strong');strong.textContent=(link.note||link.slug)+(link.auto?'（自动创建）':'');title.append(strong,document.createTextNode(' · '+link.url));
    stats.textContent='今天 '+link.today+' 次 · 近 7 天 '+link.week+' 次（'+link.weekVisitors+' 人） · 近 30 天 '+link.month+' 次';
    target.className='muted';target.textContent='跳转到：'+link.target;
    const copy=document.createElement('button');copy.type='button';copy.textContent='复制短链接';copy.onclick=safe(async()=>{await navigator.clipboard.writeText(link.url);saved(null,'已复制：'+link.url);});
    const edit=document.createElement('button');edit.type='button';edit.textContent='修改';edit.onclick=()=>{$('linkSlug').value=link.slug;$('linkTarget').value=link.target;$('linkNote').value=link.note||'';$('linkTarget').focus();};
    const remove=document.createElement('button');remove.type='button';remove.textContent='删除';remove.onclick=safe(async()=>{if(!window.confirm('删除短链接「'+link.slug+'」？已经发出去的这个短链接会失效，点击记录也会清空。'))return;renderLinks(await api('links/remove',{item:{slug:link.slug}}));saved(null,'已删除短链接');});
    row.append(title,stats,target,copy,edit,remove);box.append(row);}
}
